def slugify(s):
    s = s.lower()
    s = re.sub(r'[^a-z0-9]+', '-', s)
    return s.strip('-')

import unicodedata


def slugify(s):
    # Transliterate/deaccent characters to ASCII (e.g. 'õ' -> 'o').
    s = unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode('ascii')
    s = s.lower()

    # Every alphanumeric char is kept; everything else becomes a separator.
    slug = []
    for ch in s:
        if ch.isalnum():
            slug.append(ch)
        else:
            slug.append('-')

    # Collapse consecutive separators and trim leading/trailing ones.
    return '-'.join(part for part in ''.join(slug).split('-') if part)

